#include <iostream>
#include <unordered_map>
using namespace std;

int calculate(int n, int m) {
    if (n < m) {
        swap(n, m);
    }
    if (m == 1) {
        static unordered_map<int, int> lookup = {{0, 0}, {1, 1}, {2, 2}, {3, 3}, {4, 2}, {5, 1}};
        return lookup[n % 6];
    }
    if (n == 7) {
        if (m == 2) {
            return 2;
        }
        return (n * m) % 2;
    } else if (n >= 4) {
        return (n * m) % 2;
    } else {
        static unordered_map<pair<int, int>, int, hash_pair> conditions = {
            {{3, 2}, 2},
            {{3, 1}, 3},
            {{2, 2}, 4},
            {{2, 1}, 2}
        };
        auto it = conditions.find({n, m});
        if (it != conditions.end()) {
            return it->second;
        } else {
            return (n * m) % 2;
        }
    }
}

int main() {
    int a, b;
    cin >> a >> b;
    cout << a * b - calculate(a, b) << endl;
    return 0;
}
